<?php
require dirname(__DIR__).'/includes/bootstrap.php';require APP_ROOT.'/services/catalog.php';$u=require_permission('QUAN_LY_KHO');$headers=['so_khung_vin','ma_cau_hinh','ma_showroom','so_may','mau_sac','nam_san_xuat','gia_von','ngay_nhap_dau'];
handle_form(function()use($u,$headers){if(post('action')==='preview'){$f=$_FILES['file']??[];must(($f['error']??1)===0&&$f['size']<=5*1024*1024,'Tệp không hợp lệ hoặc lớn hơn 5 MB.');$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));must(in_array($ext,['csv','xlsx'],true),'Chỉ nhận CSV hoặc XLSX.');$raw=[];
 if($ext==='csv'){$h=fopen($f['tmp_name'],'r');while(($r=fgetcsv($h,0,',','"',''))!==false){$raw[]=$r;if(count($raw)>1001)break;}fclose($h);}else{$reader=new PhpOffice\PhpSpreadsheet\Reader\Xlsx();$reader->setReadDataOnly(true);$book=$reader->load($f['tmp_name']);$sheet=$book->getActiveSheet();must($sheet->getHighestDataRow()<=1001,'Tối đa 1000 xe mỗi tệp.');$raw=$sheet->toArray(null,true,true,false);$book->disconnectWorksheets();}
 must(count($raw)>1&&count($raw)<=1001,'Tệp cần 1–1000 dòng dữ liệu.');$head=array_map(fn($x)=>trim((string)$x),array_shift($raw));$head[0]=ltrim($head[0],"\xEF\xBB\xBF");must($head===$headers,'Header không đúng. Dùng mẫu CSV trên trang.');$rows=[];$errors=[];$seen=[];foreach($raw as$i=>$r){if(!array_filter($r,fn($x)=>$x!==null&&$x!==''))continue;if(count($r)!==count($headers)){$errors[]='Dòng '.($i+2).': thiếu hoặc thừa cột.';continue;}$row=array_combine($headers,array_map(fn($v)=>trim((string)$v),$r));$vin=strtoupper($row['so_khung_vin']);if(!preg_match('/^[A-HJ-NPR-Z0-9]{17}$/D',$vin)||isset($seen[$vin])||db_one('SELECT 1 FROM xe WHERE so_khung_vin=?',[$vin]))$errors[]='Dòng '.($i+2).': VIN không hợp lệ hoặc trùng.';if(!db_one('SELECT 1 FROM cau_hinh_xe WHERE ma_cau_hinh=?',[$row['ma_cau_hinh']]))$errors[]='Dòng '.($i+2).': cấu hình chưa tồn tại.';if(!scope_showroom($u,$row['ma_showroom'])||!db_one('SELECT 1 FROM showroom WHERE ma_showroom=? AND hoat_dong=1',[$row['ma_showroom']]))$errors[]='Dòng '.($i+2).': showroom không hợp lệ.';try{valid_date($row['ngay_nhap_dau']);if($row['gia_von']!=='')vnd($row['gia_von'],true);must(ctype_digit($row['nam_san_xuat'])&&(int)$row['nam_san_xuat']>=1950&&(int)$row['nam_san_xuat']<=(int)date('Y')+1&&$row['mau_sac']!=='','Năm hoặc màu chưa hợp lệ.');}catch(AppError $e){$errors[]='Dòng '.($i+2).': '.$e->getMessage();}$seen[$vin]=true;$row['so_khung_vin']=$vin;$rows[]=$row;}
 $_SESSION['import_preview']=['rows'=>$rows,'errors'=>$errors,'actor'=>$u['id'],'at'=>time()];
 }elseif(post('action')==='commit'){$preview=$_SESSION['import_preview']??[];must(($preview['actor']??0)===$u['id']&&($preview['at']??0)>time()-1800&&!empty($preview['rows'])&&empty($preview['errors']),'Bản xem trước hết hạn hoặc còn lỗi.');transaction(function()use($preview,$u){foreach($preview['rows']as$r)stock_save($u,$r);});unset($_SESSION['import_preview']);}else throw new AppError('Thao tác không hợp lệ.');
},'admin/nhap_kho.php');
page_start('Nhập kho từ CSV / Excel','Xem trước rồi xác nhận. Toàn bộ file phải hợp lệ mới ghi vào database.');echo '<div class="panel"><p>CSV UTF-8, dòng đầu:</p><code>'.e(implode(',',$headers)).'</code><p>Ngày nhập: YYYY-MM-DD HH:MM:SS; số tiền nguyên không dấu phân cách.</p>';token_form();field('file','Tệp CSV hoặc XLSX','','file','required accept=".csv,.xlsx"');echo '<button name="action" value="preview">Kiểm tra / xem trước</button></form></div>';if($p=$_SESSION['import_preview']??null){foreach($p['errors']as$err)notice($err,true);table_start($headers);foreach(array_slice($p['rows'],0,100)as$r){echo '<tr>';foreach($r as$v)echo '<td>'.e($v).'</td>';echo '</tr>';}table_end();echo '<p>'.count($p['rows']).' dòng; hiển thị tối đa 100 dòng xem trước.</p>';if(!$p['errors']){token_form();echo '<button name="action" value="commit">Nhập toàn bộ dữ liệu đã kiểm tra</button></form>';}}page_end();
